-- Campus Event Hub database. Run in Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.users(id uuid primary key default gen_random_uuid(),name varchar(80) not null check(char_length(trim(name))>=2),email varchar(254) not null unique,password_hash text not null,role text not null default 'student' check(role in ('student','admin')),created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title varchar(120) not null check(char_length(trim(title))>=3),description varchar(2000) not null check(char_length(trim(description))>=10),category text not null check(category in ('Workshop','Cultural','Technical','Sports','Club','Other')),venue varchar(160) not null check(char_length(trim(venue))>=2),starts_at timestamptz not null,capacity integer not null check(capacity between 1 and 10000),status text not null default 'published' check(status in ('published','cancelled')),created_by uuid not null references public.users(id) on delete restrict,created_at timestamptz not null default now());
create table if not exists public.registrations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events(id) on delete cascade,user_id uuid not null references public.users(id) on delete cascade,created_at timestamptz not null default now(),constraint registrations_one_per_user unique(event_id,user_id));
create index if not exists events_starts_at_idx on public.events(starts_at);create index if not exists events_category_idx on public.events(category);create index if not exists registrations_user_id_idx on public.registrations(user_id);create index if not exists registrations_event_id_idx on public.registrations(event_id);
create or replace function public.register_for_event(p_event_id uuid,p_user_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$ declare e public.events%rowtype; n integer; r public.registrations%rowtype; begin select * into e from public.events where id=p_event_id and status='published' for update; if not found then raise exception using errcode='P0001',message='This event is unavailable.'; end if; if e.starts_at<=now() then raise exception using errcode='P0001',message='Registration is closed because this event has started.'; end if; if exists(select 1 from public.registrations where event_id=p_event_id and user_id=p_user_id) then raise exception using errcode='P0001',message='You are already registered for this event.'; end if; select count(*) into n from public.registrations where event_id=p_event_id; if n>=e.capacity then raise exception using errcode='P0001',message='This event is full.'; end if; insert into public.registrations(event_id,user_id) values(p_event_id,p_user_id) returning * into r; return jsonb_build_object('id',r.id,'event_id',r.event_id,'user_id',r.user_id,'created_at',r.created_at); end; $$;
alter table public.users enable row level security;alter table public.events enable row level security;alter table public.registrations enable row level security;
-- No anon/authenticated policies: only the Express backend uses the privileged server key.
revoke all on function public.register_for_event(uuid,uuid) from public,anon,authenticated;grant execute on function public.register_for_event(uuid,uuid) to service_role;
